// @generated by:gauntlet run:godseye-e08-independent-gauntlet
import { randomUUID } from "node:crypto";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { type CodingFixture, codingFixture } from "./helpers/coding-fixture.js";

describe("E08 actual Coding Foundation runner accounting", () => {
  let f: CodingFixture;
  beforeEach(async () => {
    f = await codingFixture();
  });
  afterEach(async () => {
    await f.store.close();
  });
  const budget = (limitMicros = 30000) =>
    f.infrastructure.usage.putBudget(
      f.freshOwner(),
      {
        projectId: f.project.id,
        scope: "runner",
        scopeId: "codex",
        expectedRevision: 0,
        limitMicros,
        windowSeconds: 60,
        maxRuns: 5,
        maxConcurrent: 1,
      },
      randomUUID(),
    );
  it("T-AC-805 binds runner spend limits before an actual Coding provider submission", async () => {
    await budget(9999);
    const preparation = await f.prepare();
    await expect(f.admit(preparation)).rejects.toMatchObject({ code: "USAGE_BUDGET_EXCEEDED" });
    expect(f.provider.submissions).toHaveLength(0);
    expect((await f.infrastructure.usage.overview(f.freshOwner())).budgets[0]).toMatchObject({
      reservedMicros: 0,
      activeRuns: 0,
    });
  });
  it("T-AC-806 frees a physically stopped Coding runner while retaining conservative unknown monetary evidence", async () => {
    await budget();
    const preparation = await f.prepare(),
      task = await f.admit(preparation);
    await f.work();
    expect((await f.detail(task.id)).task.state).toBe("succeeded");
    const usage = await f.infrastructure.usage.overview(f.freshOwner());
    expect(usage.budgets[0]).toMatchObject({
      activeRuns: 0,
      reservedMicros: 0,
      spentMicros: 10000,
    });
    expect(usage.summary.estimatedMicros).toBeNull();
    const next = await f.prepare({ input: "A distinct subsequent bounded change" });
    expect((await f.admit(next)).state).toBe("queued");
    const timeline = await f.infrastructure.observability.timeline(f.freshOwner(), {
      projectId: f.project.id,
      environmentId: f.development.id,
    });
    expect(timeline.entries).toContainEqual(
      expect.objectContaining({
        id: task.id,
        kind: "coding",
        correlation: { kind: "execution", id: task.runId },
      }),
    );
  });
});
